import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, calculateDueDate } from './dates.js';

/**
 * Create a draft invoice from a customer id and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }>, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Validate customer exists
  const customer = getCustomer(customerId);
  if (!customer.ok) {
    return fail('CUSTOMER_NOT_FOUND');
  }

  // Validate issueDate format
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate and calculate due date based on terms
  const dueDate = calculateDueDate(issueDate, terms);
  if (!dueDate) {
    return fail('TERMS_INVALID');
  }

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discountPercent if provided
    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Get product from catalogue
    const product = getProduct(line.sku);
    if (!product.ok) {
      return fail('UNKNOWN_SKU');
    }

    const p = product.value;
    const lineObj = {
      sku: line.sku,
      name: p.name,
      qty: line.qty,
      unitPrice: p.unitPrice,
      vatRate: p.vatRate,
    };

    // Set discountPercent: explicit value takes precedence over tier discount
    if (line.discountPercent !== undefined) {
      lineObj.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.value.tier] ?? 0;
      if (tierDiscount > 0) {
        lineObj.discountPercent = tierDiscount;
      }
    }

    enrichedLines.push(lineObj);
  }

  return ok({
    customerId: normalizeId(customerId),
    issueDate,
    status: 'draft',
    lines: enrichedLines,
    terms,
    dueDate,
  });
}

/**
 * Calculate the total for a line item: qty times unitPrice (in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => {
    const percent = line.discountPercent ?? 0;
    const lineDiscount = Math.round(lineTotal(line) * percent / 100);
    return sum + lineDiscount;
  }, 0);

  // Calculate VAT per line on the discounted amount, rounded per line
  const vat = invoice.lines.reduce((sum, line) => {
    const total = lineTotal(line);
    const lineDiscountPercent = line.discountPercent ?? 0;
    const lineDiscount = Math.round(total * lineDiscountPercent / 100);
    const discountedAmount = total - lineDiscount;
    const lineVat = roundCents(discountedAmount * line.vatRate / 100);
    return sum + lineVat;
  }, 0);

  const total = Math.max(0, subtotal - discount + vat);
  return {
    subtotal,
    discount,
    vat,
    total,
  };
}

/**
 * Add or increase a line item on a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string, qty: number, unitPrice: number, vatRate: number, name: string, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} item
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Validate discountPercent if provided
  if (discountPercent !== undefined && !isValidDiscount(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  // Get product from catalogue
  const product = getProduct(sku);
  if (!product.ok) {
    return fail('UNKNOWN_SKU');
  }

  const p = product.value;

  // Copy lines array and check if SKU already exists
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingIndex !== -1) {
    // Increase qty of existing line
    newLines[existingIndex].qty += qty;
  } else {
    // Add new line at the end
    const lineObj = {
      sku,
      name: p.name,
      qty,
      unitPrice: p.unitPrice,
      vatRate: p.vatRate,
    };

    // Add discountPercent if provided
    if (discountPercent !== undefined) {
      lineObj.discountPercent = discountPercent;
    }

    newLines.push(lineObj);
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line item from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check invoice is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Find the line with this SKU
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  if (lineIndex === -1) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if it's the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  // Copy lines array without the line at lineIndex
  const newLines = invoice.lines.filter((_, index) => index !== lineIndex);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers
 * @returns {{ ok: true, value: { status: string, number: string } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Generate next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Check if a discount percent is valid.
 * @param {unknown} value
 * @returns {boolean}
 */
function isValidDiscount(value) {
  return typeof value === 'number' && value >= 0 && value <= 100;
}

