test('createInvoice: preserves different VAT rates from catalogue', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 1 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert.ok(result.ok);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('lineTotal: single quantity', () => {
  const line = { qty: 1, unitPrice: 9500 };
  assert.equal(lineTotal(line), 9500);
});

test('lineTotal: multiple quantity', () => {
  const line = { qty: 5, unitPrice: 9500 };
  assert.equal(lineTotal(line), 47500);
});

test('lineTotal: large amounts', () => {
  const line = { qty: 3, unitPrice: 120000 };
  assert.equal(lineTotal(line), 360000);
});

test('lineTotal: small amounts', () => {
  const line = { qty: 10, unitPrice: 50 };
  assert.equal(lineTotal(line), 500);
});

test('lineTotal: does not mutate line', () => {
  const line = { qty: 5, unitPrice: 9500 };
  const original = { ...line };
  lineTotal(line);
  assert.deepEqual(line, original);
});

test('invoiceTotals: single line', () => {
  const invoice = {
    lines: [{ qty: 8, unitPrice: 9500, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);
  // Line total: 76000, VAT 21% = 15960
  assert.equal(result.subtotal, 76000);
  assert.equal(result.vat, 15960);
  assert.equal(result.total, 91960);
});

test('invoiceTotals: multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, vatRate: 21 },
      { qty: 10, unitPrice: 9500, vatRate: 21 },
      { qty: 1, unitPrice: 120000, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  // 42500 * 21 / 100 = 8925, 95000 * 21 / 100 = 19950, 120000 * 21 / 100 = 25200
  // VAT total: 54075
  assert.equal(result.subtotal, 42500 + 95000 + 120000);
  assert.equal(result.vat, 54075);
  assert.equal(result.total, 257500 + 54075);
});

test('invoiceTotals: empty lines', () => {
  const invoice = { lines: [] };
  const result = invoiceTotals(invoice);
  assert.equal(result.subtotal, 0);
  assert.equal(result.total, 0);
});

test('invoiceTotals: subtotal with discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 6000, vatRate: 21 },
      { qty: 3, unitPrice: 7250, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  // Subtotal: 12000 + 21750 = 33750
  // VAT: 12000 * 0.21 + 21750 * 0.21 = 2520 + 4567.5 = 7087.5 -> rounds to 7088 or 7087
  // Total should include both subtotal and VAT (but no discount)
  assert.equal(result.subtotal, 33750);
  assert.ok(result.total > result.subtotal);
});

test('invoiceTotals: does not mutate invoice', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, vatRate: 21 }],
  };
  const original = JSON.stringify(invoice);
  invoiceTotals(invoice);
  assert.equal(JSON.stringify(invoice), original);
});

test('invoiceTotals: with actual invoice from createInvoice', () => {
  // C-002 is standard tier (no automatic discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.ok(result.ok);
  const totals = invoiceTotals(result.value);
  const subtotal = 8 * 9500 + 5 * 8500;
  // VAT: 76000 * 0.21 + 42500 * 0.21 = 15960 + 8925 = 24885
  const vat = 15960 + 8925;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal + vat);
});

test('addLine: add new line to invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  assert.ok(result.ok);
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'DES-HOUR', qty: 5 });
  assert.ok(addResult.ok);
  assert.equal(addResult.value.lines.length, 2);
  assert.equal(addResult.value.lines[1].sku, 'DES-HOUR');
  assert.equal(addResult.value.lines[1].qty, 5);
  assert.equal(addResult.value.lines[1].name, 'Design work (hour)');
});

test('addLine: increase qty when SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  assert.ok(result.ok);
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });
